"""Merge user data from three sources (JSON, CSV, Parquet) into one dataset.

Priority: source_a > source_b > source_c. Field names are unified per the
mapping below; conflicts per (user_id, field) are reported to conflicts.json.
"""

import json
import re

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

SOURCE_A = "/data/source_a/users.json"
SOURCE_B = "/data/source_b/users.csv"
SOURCE_C = "/data/source_c/users.parquet"
OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

FIELD_MAPPING = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status"],
}
MERGE_FIELDS = ["name", "email", "created_date", "status"]
SOURCES = ["source_a", "source_b", "source_c"]  # priority order
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def normalize_date(value, user_id, source):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    ts = pd.to_datetime(value, errors="coerce")
    if pd.isna(ts):
        raise ValueError(f"Unparseable date {value!r} for user {user_id} in {source}")
    return ts.strftime("%Y-%m-%d")


def normalize_records(df, source):
    """Rename mapped columns and return {user_id: {field: value}} records."""
    rename = {}
    for unified, aliases in FIELD_MAPPING.items():
        for alias in aliases:
            if alias in df.columns:
                rename[alias] = unified
                break
    df = df.rename(columns=rename)
    missing = [f for f in ("user_id", "name", "email", "created_date") if f not in df.columns]
    if missing:
        raise ValueError(f"{source}: missing required columns after mapping: {missing}")

    records = {}
    for row in df.to_dict("records"):
        uid = int(row["user_id"])
        if uid in records:
            raise ValueError(f"{source}: duplicate user_id {uid}")
        rec = {"user_id": uid}
        for field in MERGE_FIELDS:
            value = row.get(field)
            if value is None or (isinstance(value, float) and pd.isna(value)):
                value = None
            elif field == "created_date":
                value = normalize_date(value, uid, source)
            else:
                value = str(value)
            rec[field] = value
        records[uid] = rec
    return records


def load_sources():
    with open(SOURCE_A) as f:
        a = normalize_records(pd.DataFrame(json.load(f)), "source_a")
    b = normalize_records(pd.read_csv(SOURCE_B, dtype=str), "source_b")
    c = normalize_records(pq.read_table(SOURCE_C).to_pandas(), "source_c")
    return {"source_a": a, "source_b": b, "source_c": c}


def merge(data):
    all_ids = sorted(set().union(*(d.keys() for d in data.values())))
    merged_rows = []
    conflicts = []

    for uid in all_ids:
        present = {s: data[s][uid] for s in SOURCES if uid in data[s]}
        row = {"user_id": uid}
        for field in MERGE_FIELDS:
            selected = next((present[s][field] for s in SOURCES if present[s][field] is not None), None)
            row[field] = selected
            if len(present) > 1:
                values = {s: rec[field] for s, rec in present.items() if rec[field] is not None}
                if len(set(values.values())) > 1:
                    conflicts.append({
                        "user_id": uid,
                        "field": field,
                        "values": values,
                        "selected": selected,
                    })
        merged_rows.append(row)
    return merged_rows, conflicts


def main():
    data = load_sources()
    merged_rows, conflicts = merge(data)

    schema = pa.schema([
        ("user_id", pa.int64()),
        ("name", pa.string()),
        ("email", pa.string()),
        ("created_date", pa.string()),
        ("status", pa.string()),
    ])
    table = pa.Table.from_pylist(merged_rows, schema=schema)
    pq.write_table(table, OUT_PARQUET)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w") as f:
        json.dump(report, f, indent=2)

    print(f"Merged {len(merged_rows)} users -> {OUT_PARQUET}")
    print(f"{len(conflicts)} conflicts -> {OUT_CONFLICTS}")


if __name__ == "__main__":
    main()

